Here is the commit message:
iio: gyro: mpu3050: Move iio_device_register() to correct
 location

iio_device_register() should be at the end of the probe function to
prevent race conditions.

Place iio_device_register() at the end of the probe function and place
iio_device_unregister() accordingly.

Fixes: 3904b28efb2c7 ("iio: gyro: Add driver for the MPU-3050 gyroscope")
Suggested-by: Jonathan Cameron <jic23@kernel.org>
Reviewed-by: Linus Walleij <linusw@kernel.org>
Signed-off-by: Ethan Tidmore <ethantidmore06@gmail.com>
Reviewed-by: Andy Shevchenko <andriy.shevchenko@intel.com>
Cc: <Stable@vger.kernel.org>
Signed-off-by: Jonathan Cameron <Jonathan.Cameron@huawei.com>

Here is the root cause:
The bug was caused by calling `iio_device_register()` too early in the probe function, before all device resources (PM runtime, IRQ, trigger setup) were fully initialized. This allowed userspace to access the device via sysfs or other interfaces before it was ready, leading to race conditions and potential crashes or undefined behavior. The fix moves `iio_device_register()` to the end of probe, after all initialization is complete, and adjusts the error path and remove function accordingly to maintain correct order.

Here is the patch:

 int mpu3050_common_probe(struct device *dev,
 			 struct regmap *map,
 			 int irq,
 			 const char *name)
 {
 	struct iio_dev *indio_dev;
 	struct mpu3050 *mpu3050;
 	unsigned int val;
 	int ret;

 	indio_dev = devm_iio_device_alloc(dev, sizeof(*mpu3050));
 	if (!indio_dev)
 		return -ENOMEM;
 	mpu3050 = iio_priv(indio_dev);

 	mpu3050->dev = dev;
 	mpu3050->map = map;
 	mutex_init(&mpu3050->lock);
 	/* Default fullscale: 2000 degrees per second */
 	mpu3050->fullscale = FS_2000_DPS;
 	/* 1 kHz, divide by 100, default frequency = 10 Hz */
 	mpu3050->lpf = MPU3050_DLPF_CFG_188HZ;
 	mpu3050->divisor = 99;

 	/* Read the mounting matrix, if present */
 	ret = iio_read_mount_matrix(dev, &mpu3050->orientation);
 	if (ret)
 		return ret;

 	/* Fetch and turn on regulators */
 	mpu3050->regs[0].supply = mpu3050_reg_vdd;
 	mpu3050->regs[1].supply = mpu3050_reg_vlogic;
 	ret = devm_regulator_bulk_get(dev, ARRAY_SIZE(mpu3050->regs),
 				      mpu3050->regs);
 	if (ret)
 		return dev_err_probe(dev, ret, "Cannot get regulators\n");

 	ret = mpu3050_power_up(mpu3050);
 	if (ret)
 		return ret;

 	ret = regmap_read(map, MPU3050_CHIP_ID_REG, &val);
 	if (ret) {
 		dev_err(dev, "could not read device ID\n");
 		ret = -ENODEV;

 		goto err_power_down;
 	}

 	if ((val & MPU3050_CHIP_ID_MASK) != MPU3050_CHIP_ID) {
 		dev_err(dev, "unsupported chip id %02x\n",
 				(u8)(val & MPU3050_CHIP_ID_MASK));
 		ret = -ENODEV;
 		goto err_power_down;
 	}

 	ret = regmap_read(map, MPU3050_PRODUCT_ID_REG, &val);
 	if (ret) {
 		dev_err(dev, "could not read device ID\n");
 		ret = -ENODEV;

 		goto err_power_down;
 	}
 	dev_info(dev, "found MPU-3050 part no: %d, version: %d\n",
 		 ((val >> 4) & 0xf), (val & 0xf));

 	ret = mpu3050_hw_init(mpu3050);
 	if (ret)
 		goto err_power_down;

 	indio_dev->channels = mpu3050_channels;
 	indio_dev->num_channels = ARRAY_SIZE(mpu3050_channels);
 	indio_dev->info = &mpu3050_info;
 	indio_dev->available_scan_masks = mpu3050_scan_masks;
 	indio_dev->modes = INDIO_DIRECT_MODE;
 	indio_dev->name = name;

 	ret = iio_triggered_buffer_setup(indio_dev, iio_pollfunc_store_time,
 					 mpu3050_trigger_handler,
 					 &mpu3050_buffer_setup_ops);
 	if (ret) {
 		dev_err(dev, "triggered buffer setup failed\n");
 		goto err_power_down;
 	}

-	ret = iio_device_register(indio_dev);
-	if (ret) {
-		dev_err(dev, "device register failed\n");
-		goto err_cleanup_buffer;
-	}
-
 	dev_set_drvdata(dev, indio_dev);

 	/* Check if we have an assigned IRQ to use as trigger */
 	if (irq) {
 		ret = mpu3050_trigger_probe(indio_dev, irq);
 		if (ret)
 			dev_err(dev, "failed to register trigger\n");
 	}

 	/* Enable runtime PM */
 	pm_runtime_get_noresume(dev);
 	pm_runtime_set_active(dev);
 	pm_runtime_enable(dev);
 	/*
 	 * Set autosuspend to two orders of magnitude larger than the
 	 * start-up time. 100ms start-up time means 10000ms autosuspend,
 	 * i.e. 10 seconds.
 	 */
 	pm_runtime_set_autosuspend_delay(dev, 10000);
 	pm_runtime_use_autosuspend(dev);
 	pm_runtime_put(dev);

+	ret = iio_device_register(indio_dev);
+	if (ret) {
+		dev_err(dev, "device register failed\n");
+		goto err_iio_device_register;
+	}
+
 	return 0;

-err_cleanup_buffer:
+err_iio_device_register:
+	pm_runtime_get_sync(dev);
+	pm_runtime_put_noidle(dev);
+	pm_runtime_disable(dev);
+	if (irq)
+		free_irq(mpu3050->irq, mpu3050->trig);
 	iio_triggered_buffer_cleanup(indio_dev);
 err_power_down:
 	mpu3050_power_down(mpu3050);

 	return ret;
 }

 void mpu3050_common_remove(struct device *dev)
 {
 	struct iio_dev *indio_dev = dev_get_drvdata(dev);
 	struct mpu3050 *mpu3050 = iio_priv(indio_dev);

+	iio_device_unregister(indio_dev);
 	pm_runtime_get_sync(dev);
 	pm_runtime_put_noidle(dev);
 	pm_runtime_disable(dev);
 	iio_triggered_buffer_cleanup(indio_dev);
 	if (mpu3050->irq)
 		free_irq(mpu3050->irq, mpu3050->trig);
-	iio_device_unregister(indio_dev);
 	mpu3050_power_down(mpu3050);
 }



